begin;
create table public.collection_settings (key text primary key default 'default' check(key='default'), show_featured_collection boolean not null default true, default_shop_sort text not null default 'featured' check(default_shop_sort in ('featured','name','price')), products_per_page integer not null default 12 check(products_per_page between 1 and 100), show_prices boolean not null default true, show_price_on_request_label boolean not null default true, updated_at timestamptz not null default now(), updated_by uuid references public.profiles(id) on delete set null);
create table public.admin_audit_log (id uuid primary key default extensions.gen_random_uuid(), actor_id uuid references public.profiles(id) on delete set null, action text not null, entity_type text not null, entity_id uuid, safe_summary text not null, metadata jsonb not null default '{}'::jsonb, request_id uuid, ip_hash text, created_at timestamptz not null default now());
create table public.import_jobs (id uuid primary key default extensions.gen_random_uuid(), status text not null default 'pending' check(status in ('pending','validating','running','completed','failed','rolled_back')), schema_version integer not null check(schema_version>0), source_type text not null, started_by uuid references public.profiles(id) on delete set null, started_at timestamptz not null default now(), completed_at timestamptz, summary jsonb not null default '{}'::jsonb, error_summary text, backup_reference text);
insert into public.collection_settings(key) values('default') on conflict(key) do nothing;
commit;
